# application.properties
app.api.key=abc123xyz
app.api.timeout=5000
app.api.max-retries=3
app.api.base-url=https://api.example.com

// Approach 1: @Value (scattered single properties)
@Service
public class PaymentService {
    @Value("${app.api.key}")
    private String apiKey;  // simple field injection

    @Value("${app.api.timeout}")
    private int timeout;
}

// Approach 2: @ConfigurationProperties (grouped)
@ConfigurationProperties(prefix = "app.api")
public record ApiConfig(
    String key,           // maps to app.api.key
    int timeout,          // maps to app.api.timeout
    int maxRetries,       // maps to app.api.max-retries (kebab-case converts)
    String baseUrl
) {}

@Configuration
@EnableConfigurationProperties(ApiConfig.class)
public class AppConfiguration {}  // register the config bean

@Service
public class PaymentService {
    private final ApiConfig apiConfig;

    public PaymentService(ApiConfig apiConfig) {  // inject the whole config
        this.apiConfig = apiConfig;
    }
}
