# application-dev.properties (local development with H2)
spring.datasource.url=jdbc:h2:mem:devdb
spring.jpa.hibernate.ddl-auto=create-drop  // safe for in-memory db, recreates on restart
spring.jpa.show-sql=true  // see generated SQL for learning

# application-test.properties (integration tests)
spring.datasource.url=jdbc:h2:mem:testdb
spring.jpa.hibernate.ddl-auto=create-drop  // each test gets a fresh schema

# application-prod.properties (production)
spring.datasource.url=jdbc:postgresql://prod-db:5432/orders
spring.jpa.hibernate.ddl-auto=validate  // only check, never modify
# Schema changes handled by Flyway migrations, not Hibernate

@Entity
public class Order {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String customerName;
    private BigDecimal totalAmount;
    private LocalDateTime orderDate;

    // If you add a new field here and use ddl-auto=update,
    // Hibernate tries to ALTER TABLE to add the column.
    // If you use ddl-auto=validate, startup fails if the column doesn't exist.
    // If you use ddl-auto=none, Hibernate doesn't care about the schema.
}
